bounded_host_request.command:
set -euo pipefail
name=gace-createvdobot-videobot-poll-1
test "$(docker inspect -f '{{.State.Running}}' "$name" 2>/dev/null)" = true || exit 61
docker logs --tail 200 "$name" 2>&1 | grep -q '^CREATOR_DM_POLL_READY=PASS$' || exit 62
docker exec -i "$name" node --input-type=module - <<'NODE'
import pg from 'pg';import {readFileSync} from 'node:fs';
const e=process.env,id='sp_76f23430d1c29ca355960a95';
const db=new pg.Pool({host:e.VIDEOBOT_DB_HOST,database:e.VIDEOBOT_DB_NAME,user:e.VIDEOBOT_DB_USER,password:readFileSync(e.VIDEOBOT_DB_PASSWORD_FILE,'utf8').trim(),max:1});
try{
 const q=await db.query("SELECT p.price_stars,p.pack_name,p.status AS product_status,t.status,t.chat_id,t.message_thread_id,t.telegram_message_id,t.display_text FROM videobot_sticker_products p JOIN videobot_sticker_topic_posts t ON t.product_id=p.product_id WHERE p.product_id=$1",[id]);
 if(q.rowCount!==1)throw Error('STK_CATALOG_MISSING');
 const p=q.rows[0];
 if(p.status!=='sent'||p.product_status!=='published'||Number(p.price_stars)!==50||
 Number(p.chat_id)!==-1002373696859||Number(p.message_thread_id)!==4640||
 !Number.isSafeInteger(Number(p.telegram_message_id))||Number(p.telegram_message_id)<=4664||
 !p.display_text?.includes('50 Stars')||!p.display_text?.includes('個'))
 throw Error('STK_CATALOG_READBACK_MISMATCH');
 console.log('STK_CATALOG_POST_RECEIPT=PASS');
 console.log('STK_CATALOG_MESSAGE_ID='+p.telegram_message_id);
 const x=await db.query("SELECT COUNT(*)::int AS n FROM videobot_sticker_orders WHERE product_id=$1",[id]);
 console.log('STK_CATALOG_ORDERS='+x.rows[0].n);
}finally{await db.end();}
NODE
echo STK_CATALOG_LIVE_DB_READBACK=PASS
